			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		if _, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role); err != nil {
			return protocol.Result{}, false, err
		}

		// Insert the request before touching purchases.  The unique scoped key
		// serializes concurrent callers; a failed transaction rolls it back.
		inserted, err := tx.Exec(ctx, `
			INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6::jsonb)
			ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING`,
			u.Tenant, u.User, operation, key, requestHash, string(responseJSON))
		if err != nil {
			return protocol.Result{}, false, err
		}
		if inserted.RowsAffected() == 0 {
			var storedHash string
			if err = tx.QueryRow(ctx, `SELECT "requestHash" FROM "ActionRequest"
				WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4`,
				u.Tenant, u.User, operation, key).Scan(&storedHash); err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != requestHash {
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return response, true, nil
		}

		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase"
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3
			AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := make([]string, 0, len(ids))
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		if err = rows.Err(); err != nil {
			rows.Close()
			return protocol.Result{}, false, err
		}
		rows.Close()
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		updated, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if updated.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		for _, id := range ids {
			if _, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit"
				("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
				VALUES ($1,$2,$3,$4,$5,'submitted','approved')`,
				u.Tenant, id, u.User, operation, key); err != nil {
				return protocol.Result{}, false, err
			}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return response, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func hashRequest(ids []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ids {
		_, _ = fmt.Fprintf(h, "%d:%s", len([]byte(id)), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

